import{_ as a,o as n,c as t,ag as i}from"./chunks/framework.WIXs2PCf.js";const u=JSON.parse('{"title":"Maintaining and releasing","description":"","frontmatter":{},"headers":[],"relativePath":"maintaining.md","filePath":"maintaining.md"}'),o={name:"maintaining.md"};function s(r,e,l,c,d,p){return n(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="maintaining-and-releasing" tabindex="-1">Maintaining and releasing <a class="header-anchor" href="#maintaining-and-releasing" aria-label="Permalink to &quot;Maintaining and releasing&quot;">​</a></h1><p>The public repository is a curated distribution of the integration maintained with the platform. It contains the built package, documentation, optional skill and runnable website example. It does not contain the private platform source or backend configuration.</p><h2 id="one-source-for-documentation" tabindex="-1">One source for documentation <a class="header-anchor" href="#one-source-for-documentation" aria-label="Permalink to &quot;One source for documentation&quot;">​</a></h2><p>Each topic starts as Markdown. VitePress renders the guides and Redocly renders the OpenAPI 3.1 reference. The build also creates raw Markdown, <code>llms.txt</code>, <code>llms-full.txt</code>, package documentation and skill references from the same inputs. Change the maintained source and regenerate; do not make incompatible corrections in one generated copy. Published package versions contain their own documentation snapshot. The Pages site follows the latest repository version.</p><h2 id="development-verification" tabindex="-1">Development verification <a class="header-anchor" href="#development-verification" aria-label="Permalink to &quot;Development verification&quot;">​</a></h2><p>In the platform repository, build the SDK and package, run the controller/transport tests, type-check and lint affected workspaces, and build/test the playground. The transport is shared with the hosted funnel; validate that the hosted funnel still compiles when it changes. Export only the allowlisted integration files.</p><p>The packed release must install in an empty project without private workspace dependencies. Check its JavaScript entry points, declaration resolution and runnable example. Inspect <code>npm pack --dry-run</code> before publication. A package that only works through workspace symlinks is not ready.</p><h2 id="public-repository" tabindex="-1">Public repository <a class="header-anchor" href="#public-repository" aria-label="Permalink to &quot;Public repository&quot;">​</a></h2><p>The root package contains prebuilt JavaScript and declarations; consumers do not rebuild platform internals. Install the root and <code>examples/playground</code> dependencies to run the example against the included package. The Pages output is in <code>docs/</code>, with <code>.nojekyll</code>, and is served from <code>main:/docs</code>. It contains VitePress guides, a Redoc reference, the OpenAPI document and the built network-free playground. Sources live in <code>site/</code> and <code>openapi.json</code>. Run <code>npm run docs:dev</code> for VitePress development or <code>npm run docs:build</code> to lint the OpenAPI spec and rebuild all documentation. The brand theme extends the standard VitePress theme; it does not replace its search or navigation.</p><h2 id="publish" tabindex="-1">Publish <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;Publish&quot;">​</a></h2><p>A maintainer with npm organization access publishes from the curated repository after verification:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --access</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public</span></span></code></pre></div><p>npm may require interactive second-factor approval. Credentials stay in the maintainer&#39;s npm configuration, never in the repository. Increment the version for later releases; published version contents cannot be replaced. Verify the registry version and perform a fresh install after publishing. Tag the matching public repository commit only after the corresponding npm publication succeeds.</p><p>This release does not configure an automated npm publisher or save a long-lived token in GitHub. Organization maintainers can separately configure trusted publishing for future releases.</p>`,14)])])}const m=a(o,[["render",s]]);export{u as __pageData,m as default};
